body:
You can add this to ensure OS name is capitalized properly in the editor:

```diff
diff --git a/editor/inspector/editor_property_name_processor.cpp b/editor/inspector/editor_property_name_processor.cpp
index e94aff2dea..61df2cb340 100644
--- a/editor/inspector/editor_property_name_processor.cpp
+++ b/editor/inspector/editor_property_name_processor.cpp
@@ -250,6 +250,7 @@ EditorPropertyNameProcessor::EditorPropertyNameProcessor() {
        capitalize_string_remaps["ok"] = "OK";
        capitalize_string_remaps["opengl"] = "OpenGL";
        capitalize_string_remaps["opengl3"] = "OpenGL 3";
+       capitalize_string_remaps["openharmony"] = "OpenHarmony";
        capitalize_string_remaps["opentype"] = "OpenType";
        capitalize_string_remaps["openxr"] = "OpenXR";
        capitalize_string_remaps["osslsigncode"] = "osslsigncode";
```
